-- AlterTable
ALTER TABLE "contas_garantidas_usos" ADD COLUMN     "jurosReal" DECIMAL(18,2);
ALTER TABLE "contas_garantidas_usos" ADD COLUMN     "iofReal" DECIMAL(18,2);

-- Substitui a importacao de historico de Conta Garantida da migration
-- 20260905130000 por valores reais informados diretamente (jurosReal/iofReal),
-- em vez de um valorUtilizado calculado de tras pra frente pra bater com o
-- juros - a pedido do usuario, sem usar formula nenhuma, so os numeros exatos
-- de "JUROS DE CONTA GARANTIDA.pdf" / "IOF DE CONTA GARANTIDA.pdf" (jan/25 a
-- jul/26, versao com todas as colunas legiveis).
--
-- valorUtilizado fica 0 nessas 119 utilizacoes: e um campo
-- obrigatorio no banco mas o PDF so tem juros/IOF totais do mes, nao o saldo
-- utilizado. Tentar achar um "saldo do mes" que reproduza o IOF do PDF pela
-- formula do sistema (0,0082%/dia) gera valores que ultrapassam o proprio
-- limite contratado em boa parte dos meses (conta garantida e revolvente -
-- varios saques/pagamentos dentro do mes acumulam mais IOF do que um saldo
-- medio fixo explicaria) - por isso a decisao de nao estimar nada e deixar
-- 0. O grafico "Evolucao do valor utilizado" nao reflete esses meses.
--
-- SANTANDER: existem 2 contas cadastradas (taxa 16,2% e 2,16%) mas o PDF so
-- tem uma coluna - valor splitado proporcionalmente ao limite contratado de
-- cada uma (250.000 e 500.000 = peso 1:2). A soma das duas bate exatamente
-- com o PDF.
--
-- BS2 nao tem conta garantida cadastrada ainda - dados do BS2 nao importados.

DELETE FROM "contas_garantidas_usos" WHERE "observacao" LIKE 'Juros de%importado de JUROS/IOF DE CONTA GARANTIDA.pdf%';

